import{_ as e,c as a,o as t,a4 as s}from"./chunks/framework.DzOtv0XR.js";const f=JSON.parse('{"title":"Next.js","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/next.md","filePath":"frameworks/next.md"}'),r={name:"frameworks/next.md"},l=s(`<h1 id="next-js" tabindex="-1">Next.js <a class="header-anchor" href="#next-js" aria-label="Permalink to &quot;Next.js&quot;">​</a></h1><p><code>Next.js</code> 是一个 React 应用程序的服务端渲染框架、全栈框架</p><p>集成 css module</p><p>服务商级别的优化和便利</p><h2 id="hello-world-示例" tabindex="-1">Hello World 示例 <a class="header-anchor" href="#hello-world-示例" aria-label="Permalink to &quot;Hello World 示例&quot;">​</a></h2><p>pages -&gt; next -&gt; next build -&gt; next start(prod)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>mkdir hello-next</span></span>
<span class="line"><span>cd hello-next</span></span>
<span class="line"><span>npm init -y</span></span>
<span class="line"><span>npm install --save react react-dom next</span></span>
<span class="line"><span>mkdir pages</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;scripts&quot;: {</span></span>
<span class="line"><span>    &quot;dev&quot;: &quot;next&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import Link from &#39;next/link&#39;</span></span></code></pre></div><p>pages 目录最关键，不可变</p><h2 id="与-nest-js-区别" tabindex="-1">与 Nest.js 区别 <a class="header-anchor" href="#与-nest-js-区别" aria-label="Permalink to &quot;与 Nest.js 区别&quot;">​</a></h2><p><code>Nest.js</code> 是一个基于 Node.js 平台的开发框架，类似 eggjs</p><h2 id="fast-refresh" tabindex="-1">fast refresh <a class="header-anchor" href="#fast-refresh" aria-label="Permalink to &quot;fast refresh&quot;">​</a></h2><ul><li>类似于 HMR（热模块替换），允许在开发过程中实时查看更改。</li></ul><h2 id="编译" tabindex="-1">编译 <a class="header-anchor" href="#编译" aria-label="Permalink to &quot;编译&quot;">​</a></h2><p>5000个模块，intel 编译 5-10s，m1 2-4s，快一倍</p><p><a href="https://gist.github.com/gaearon/9d6b8eddc7f5e647a054d7b333434ef6" target="_blank" rel="noreferrer">Next.js SPA example with dynamic client-only routing and static hosting</a></p><p><a href="https://julesblom.com/writing/map-of-react-api" target="_blank" rel="noreferrer">Map of React API - JulesBlom.com</a></p><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><ol><li>编译 pages 目录的文件</li><li>根据文件结构生成路由配置表</li><li>根据请求路径查询路由表并动态加载页面文件</li></ol><h2 id="image-组件" tabindex="-1">Image 组件 <a class="header-anchor" href="#image-组件" aria-label="Permalink to &quot;Image 组件&quot;">​</a></h2><ul><li>性能优化：选择最优格式和体积。</li><li>提供占位符。</li><li>内置代理服务器处理远程图片。</li></ul><h2 id="打包部署" tabindex="-1">打包部署 <a class="header-anchor" href="#打包部署" aria-label="Permalink to &quot;打包部署&quot;">​</a></h2><ul><li>默认输出到 <code>.next</code> 文件夹。</li><li><strong>自托管</strong>：需维护 Node.js 环境，体验和维护成本较高。</li><li><strong>静态托管</strong>：可以将应用导出为纯静态网站。</li></ul><p><a href="https://nextjs.org/docs/advanced-features/static-html-export" target="_blank" rel="noreferrer">Advanced Features: Static HTML Export | Next.js</a></p><h3 id="vercel-部署优化" tabindex="-1">Vercel 部署优化 <a class="header-anchor" href="#vercel-部署优化" aria-label="Permalink to &quot;Vercel 部署优化&quot;">​</a></h3><ul><li>API 路由走 serverless function，无限扩容。</li><li>Middleware 走 edge function，快速启动。</li><li>使用 Git 钩子进行自动部署。</li></ul><h3 id="部署到-cloudflare" tabindex="-1">部署到 cloudflare <a class="header-anchor" href="#部署到-cloudflare" aria-label="Permalink to &quot;部署到 cloudflare&quot;">​</a></h3><p><a href="https://github.com/cloudflare/next-on-pages" target="_blank" rel="noreferrer">https://github.com/cloudflare/next-on-pages</a> 基于已有项目执行</p><h3 id="多服务器" tabindex="-1">多服务器 <a class="header-anchor" href="#多服务器" aria-label="Permalink to &quot;多服务器&quot;">​</a></h3><p>build id 是随机的，多个不同的构建会导致缓存失效。解决方案是定制 buid id 方法，比如使用 git commit id</p><p><a href="https://levelup.gitconnected.com/how-to-deploy-next-js-on-multiple-servers-3b493d4ce0e9" target="_blank" rel="noreferrer">How To Deploy Next.js on Multiple Servers | Level Up Coding</a></p><h2 id="数据获取" tabindex="-1">数据获取 <a class="header-anchor" href="#数据获取" aria-label="Permalink to &quot;数据获取&quot;">​</a></h2><ul><li><strong><code>getStaticProps</code></strong>：构建时预渲染，不常变化的数据。</li><li><strong><code>getServerSideProps</code></strong>：实时获取数据。</li><li><strong><code>getStaticPaths</code></strong>：构建时生成静态页面，支持动态路由。</li></ul><blockquote><p>在构建时，Next.js将使用getStaticPaths返回的参数值来生成静态页面。对于每个参数值，Next.js将调用getStaticProps函数，获取该参数的静态数据，并将其传递给页面组件作为props。</p></blockquote><p>![[image/next-1722578971144.webp]]</p><h2 id="国内" tabindex="-1">国内 <a class="header-anchor" href="#国内" aria-label="Permalink to &quot;国内&quot;">​</a></h2><ul><li>Umi、Midway、Nest.js 和 Next.js 是主要选择。</li></ul><h2 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h2><p>不适合深度定制 适合大厂吗？</p><p><a href="https://mp.weixin.qq.com/s/5Ir7EoHLo37bs6W5WNa-Tw" target="_blank" rel="noreferrer">我看Next.js：一个更现代的海王</a></p><pre><code>Next.js 的事情相当复杂。开发服务器做了太多事情。复杂度转移，开发简单，部署迁移复杂。
</code></pre><p>可迁移性不确定、支持度不确定。平台捆绑。</p><p><a href="https://zhuhaow.me/want-nextjs-at-edge-just-use-vercel/" target="_blank" rel="noreferrer">Want Next.js at the edge? Just use Vercel | Not a blog</a></p><p><a href="https://www.v2ex.com/t/938396" target="_blank" rel="noreferrer">https://www.v2ex.com/t/938396</a></p><h2 id="prisma" tabindex="-1">prisma <a class="header-anchor" href="#prisma" aria-label="Permalink to &quot;prisma&quot;">​</a></h2><p>[[prisma]]</p>`,45),n=[l];function o(i,p,c,d,h,u){return t(),a("div",null,n)}const g=e(r,[["render",o]]);export{f as __pageData,g as default};
